KeywordList = KeywordList.replace(/[^A-Za-z\s]/g, "");
KeywordList = KeywordList.toLowerCase();
let Keyword = KeywordList.split(/\s+/);

// Create a lookup Set of phrases already in KeywordArray
    let SetOfKeywords = new Set(KeywordArray.map(item => item[0]));

// Loop to add double words to KeywordArray
    for (let i = 0; i < Keyword.length - 1; i++) {
        let word1 = Keyword[i];
        let word2 = Keyword[i + 1];

        // Limit length to more then 4 char
        if (word1.length > 4 && word2.length > 4) {
            let DoubleKeyword = word1 + " " + word2;

            // Instantly check if we already have it (no inner loop needed!)
            if (!SetOfKeywords.has(DoubleKeyword)) {
                SetOfKeywords.add(DoubleKeyword); // Add to our tracker so we don't duplicate
                KeywordArray.push([DoubleKeyword, 0]);
            }
        }
    }
